// src/logger.ts
// 日志输出
export type LogLevel = 'debug' | 'info' | 'warn' | 'error';

const LEVEL_ORDER: Record<LogLevel, number> = {
  debug: 10,
  info: 20,
  warn: 30,
  error: 40,
};

/**
 * 输出一条日志。若消息级别低于配置的 logLevel 阈值则被抑制（返回 null）。
 */
export function log(level: LogLevel, message: string, configured: LogLevel = 'info'): string | null {
  if (LEVEL_ORDER[level] < LEVEL_ORDER[configured]) {
    return null;
  }
  return `[${level}] ${message}`;
}

// src/config-schema.ts
// 配置 schema 与解析
import type { LogLevel } from './logger.js';

export interface AppConfig {
  name: string;
  logLevel: LogLevel;
}

const VALID_LOG_LEVELS: readonly LogLevel[] = ['debug', 'info', 'warn', 'error'];

export function parseConfig(raw: Record<string, unknown>): AppConfig {
  if (typeof raw.name !== 'string' || raw.name.length === 0) {
    throw new Error('name is required');
  }
  const logLevel: LogLevel = raw.logLevel === undefined ? 'info' : (raw.logLevel as LogLevel);
  if (!VALID_LOG_LEVELS.includes(logLevel)) {
    throw new Error(`logLevel must be one of: ${VALID_LOG_LEVELS.join(', ')}`);
  }
  return { name: raw.name, logLevel };
}

