import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { parseConfig } from '../src/config-schema.js';
import { loadConfig } from '../src/loader.js';
import { log } from '../src/logger.js';

describe('config 基础', () => {
  it('name 解析', () => {
    expect(parseConfig({ name: 'svc' }).name).toBe('svc');
  });
  it('name 缺失抛错', () => {
    expect(() => parseConfig({})).toThrow('name');
  });
});

describe('logLevel 配置', () => {
  it('默认值为 info', () => {
    expect(parseConfig({ name: 'svc' }).logLevel).toBe('info');
  });
  it('解析合法 logLevel', () => {
    expect(parseConfig({ name: 'svc', logLevel: 'debug' }).logLevel).toBe('debug');
    expect(parseConfig({ name: 'svc', logLevel: 'info' }).logLevel).toBe('info');
    expect(parseConfig({ name: 'svc', logLevel: 'warn' }).logLevel).toBe('warn');
    expect(parseConfig({ name: 'svc', logLevel: 'error' }).logLevel).toBe('error');
  });
  it('非法 logLevel 被拒绝', () => {
    expect(() => parseConfig({ name: 'svc', logLevel: 'verbose' })).toThrow('logLevel');
    expect(() => parseConfig({ name: 'svc', logLevel: 42 })).toThrow('logLevel');
    expect(() => parseConfig({ name: 'svc', logLevel: '' })).toThrow('logLevel');
  });
});

describe('loadConfig 加载器', () => {
  let dir: string;
  beforeEach(() => {
    dir = mkdtempSync(join(tmpdir(), 'cfg-test-'));
  });
  afterEach(() => {
    rmSync(dir, { recursive: true, force: true });
  });

  const writeCfg = (data: unknown): string => {
    const p = join(dir, 'config.json');
    writeFileSync(p, JSON.stringify(data));
    return p;
  };

  it('加载合法配置', () => {
    const cfg = loadConfig(writeCfg({ name: 'svc', logLevel: 'warn' }));
    expect(cfg).toEqual({ name: 'svc', logLevel: 'warn' });
  });
  it('未指定 logLevel 时默认为 info', () => {
    const cfg = loadConfig(writeCfg({ name: 'svc' }));
    expect(cfg.logLevel).toBe('info');
  });
  it('非法 logLevel 被加载器拒绝', () => {
    expect(() => loadConfig(writeCfg({ name: 'svc', logLevel: 'trace' }))).toThrow('logLevel');
  });
});

describe('logger 基础', () => {
  it('log 输出带级别前缀', () => {
    expect(log('info', 'hi')).toBe('[info] hi');
  });
});

describe('logger 级别过滤', () => {
  it('默认阈值为 info，debug 被抑制', () => {
    expect(log('debug', 'hi')).toBeNull();
    expect(log('info', 'hi')).toBe('[info] hi');
    expect(log('error', 'hi')).toBe('[error] hi');
  });
  it('低于配置阈值的消息被抑制', () => {
    expect(log('debug', 'hi', 'info')).toBeNull();
    expect(log('info', 'hi', 'warn')).toBeNull();
  });
  it('达到或高于配置阈值的消息正常输出', () => {
    expect(log('info', 'hi', 'info')).toBe('[info] hi');
    expect(log('warn', 'hi', 'info')).toBe('[warn] hi');
    expect(log('error', 'hi', 'error')).toBe('[error] hi');
  });
});

